53	function fakeHeadlessOp(
54	  args: any,
55	  argsFn: (a: any) => { projectPath: string; params: any },
56	  projectExists: boolean = true,
57	): { error: string | null; operation: { projectPath: string; params: any } | null } {
58	  args = normalizeParameters(args || {});
59	  const { projectPath, params } = argsFn(args);
60	  if (!projectPath) return { error: 'projectPath is required.', commandArgs: null } as any;
61	  if (!validatePath(projectPath)) return { error: 'Invalid path.', commandArgs: null } as any;
62	  if (!projectExists) return { error: `Not a valid Godot project: ${projectPath}`, commandArgs: null } as any;
